#!/usr/bin/env bash
# L7 do-less overlay for contender 'ripgrep' (driver.type: cli): stdout cut to 1 line(s).
# Generated by @anybench/kit renderCliDoLessDriverScript (TDM-36): regenerate it, do not edit by hand.
#
# Verbs: start | ready | stop are no-ops (a cli keeps nothing running) | run <in> <out>.
# run writes under <out>:
#   cli/stdout.txt   stdout of the gated run (the output-diff gate compares it)
#   cli/stderr.txt   its stderr
#   cli/exit_code    its exit status
#   cli/files/       files it wrote under $CLI_FILES_OUT
#   time.txt         GNU time -v report of the gated run (collector: time)
#   hyperfine.json   hyperfine --export-json of the timed runs (collector: hyperfine)
set -euo pipefail

# The subject, as the kit wrote it. cwd is <in>; output files go under $CLI_FILES_OUT.
subject_cmd() {
  args=(--no-heading --line-number --only-matching --color never)
  # proof overlays: MAX_COUNT (do-less first-match-only), THREADS (planted regression)
  if [ -n "${MAX_COUNT:-}" ]; then args+=(--max-count "$MAX_COUNT"); fi
  if [ -n "${THREADS:-}" ]; then args+=(--threads "$THREADS"); fi
  rg "${args[@]}" -e "$(cat pattern.txt)" tree
}
# What the contender runs: the gated run and every timed run call this.
subject() { subject_cmd | head -n 1; }
export -f subject_cmd subject

contender='ripgrep'
accepted_exit_codes=' 0 1 '

die() { echo "driver.sh ($contender): $*" >&2; exit 1; }

run_subject() {
  local in="${1:?usage: driver.sh run <in> <out>}" out="${2:?usage: driver.sh run <in> <out>}"
  in="$(cd "$in" && pwd)"
  mkdir -p "$out"
  out="$(cd "$out" && pwd)"
  mkdir -p "$out/cli/files"
  local gnu_time="${ANYBENCH_GNU_TIME:-/usr/bin/time}"
  [ -x "$gnu_time" ] || die "GNU time not found at $gnu_time (the base profile installs it; set ANYBENCH_GNU_TIME)"
  command -v hyperfine > /dev/null || die "hyperfine not on PATH (the base profile installs it)"

  # 1. The gated run.
  local rc=0
  (cd "$in" && CLI_FILES_OUT="$out/cli/files" "$gnu_time" -v -o "$out/time.txt" bash -c subject) \
    > "$out/cli/stdout.txt" 2> "$out/cli/stderr.txt" || rc=$?
  printf '%s\n' "$rc" > "$out/cli/exit_code"
  case "$accepted_exit_codes" in
    *" $rc "*) ;;
    *) die "the subject exited $rc (accepted:$accepted_exit_codes); see the stderr log" ;;
  esac

  # 2. The timed runs: stdout discarded, files to a scratch dir, never to the gated outputs.
  local scratch
  scratch="$(mktemp -d)"
  if ! (cd "$in" && CLI_FILES_OUT="$scratch" hyperfine --shell=bash --style=basic --runs 10 --warmup 1 --output=null --ignore-failure --export-json "$out/hyperfine.json" --command-name "$contender" subject) \
    > "$out/cli/hyperfine.txt" 2>&1; then
    rm -rf "$scratch"
    die "hyperfine failed; see cli/hyperfine.txt"
  fi
  rm -rf "$scratch"
}

case "${1:-}" in
  start | ready | stop) exit 0 ;;
  run)
    shift
    run_subject "$@"
    ;;
  *)
    echo "usage: driver.sh start | ready | run <in> <out> | stop" >&2
    exit 2
    ;;
esac
